package com.ecommerce.payment; import com.ecommerce.order.Order; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="payments") public class Payment { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="order_id",unique=true,nullable=false) Order order; @Column(nullable=false,precision=12,scale=2) BigDecimal amount; @Enumerated(EnumType.STRING) @Column(nullable=false) Status status; @Column(name="transaction_id",unique=true) String transactionId; @Column(name="created_at",nullable=false,updatable=false) Instant createdAt; @Column(name="updated_at",nullable=false) Instant updatedAt; @PrePersist void c(){createdAt=Instant.now();updatedAt=createdAt;} @PreUpdate void u(){updatedAt=Instant.now();} public UUID getId(){return id;} public Status getStatus(){return status;} public String getTransactionId(){return transactionId;} public void setOrder(Order v){order=v;} public void setAmount(BigDecimal v){amount=v;} public void setStatus(Status v){status=v;} public void setTransactionId(String v){transactionId=v;} public enum Status{PENDING,SUCCESS,FAILED,REFUNDED} }
